using System;
using System.IO;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using CatGunner.Recovery;
using NUnit.Framework;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.SceneManagement;
using UnityEngine.TestTools;
using UnityEngine.UI;
public sealed class OriginalWeeklyRaidTests
{
 private string folder;
 private bool natural;
 private void Independent(Scene scene,LoadSceneMode mode){if(scene.name!="RecoveredClient")return;var c=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<RecoveryForestClient>(true)).Single();c.SaveFolderOverride=folder;c.Persist=true;if(!natural)foreach(var cat in c.Team.Cat_list){var combat=cat.GetComponent<ForestCombatAcceptance>();if(combat!=null)combat.enabled=false;var movement=cat.GetComponent<ForestMovementAcceptance>();if(movement!=null)movement.enabled=false;}}
 [SetUp]public void Setup(){folder=Path.Combine(Path.GetTempPath(),"catgunner-weekly-raid-"+Guid.NewGuid().ToString("N"));natural=false;Time.timeScale=1;SceneManager.sceneLoaded+=Independent;}
 [UnityTearDown]public IEnumerator Cleanup(){SceneManager.sceneLoaded-=Independent;SceneManager.sceneLoaded-=FixedCalendar;yield return SceneManager.LoadSceneAsync("RecoveredTarget");if(Directory.Exists(folder))Directory.Delete(folder,true);Time.timeScale=1;}
 private IEnumerator Load(bool tutorial=true){yield return SceneManager.LoadSceneAsync("RecoveredClient");yield return ClientStartupWait.Ready(tutorial);yield return null;}
 private static void Click(Button button){Assert.That(button!=null&&button.interactable&&button.gameObject.activeInHierarchy,Is.True,"Clickable original button required");Canvas.ForceUpdateCanvases();var r=(RectTransform)button.transform;var e=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,r.TransformPoint(r.rect.center))};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(e,hits);Assert.That(hits.Count,Is.GreaterThan(0));Assert.That(hits[0].gameObject.GetComponentInParent<Button>(),Is.SameAs(button),string.Join(" | ",hits.Take(8).Select(x=>x.gameObject.name+"/"+x.gameObject.transform.parent.name)));ExecuteEvents.ExecuteHierarchy(hits[0].gameObject,e,ExecuteEvents.pointerClickHandler);}
 private static Button At(Transform root,string path)=>root.Find(path).GetComponent<Button>();
 [UnityTest]public IEnumerator WeeklySourceEntryGateVipNavigationPreviewAndIsolatedFirstVisitReload()
 {
  yield return Load(false);var c=RecoveryForestClient.Instance;var shop=c.WeeklyShop;Assert.That(c.Tutorial.DisableOnTutorial.Count(g=>g!=null),Is.EqualTo(4));Assert.That(shop.WeeklyShop_Btn_obj.activeSelf,Is.False);c.State.Gun_Collect[15]=true;shop.Btn_Reload();Assert.That(shop.WeeklyShop_Btn_obj.activeSelf,Is.True,"Weekly entry is not in the original tutorial disable list");c.Tutorial.SetCleared();yield return null;
  c.State.Gun_Collect[15]=false;c.State.Gun_Collect[14]=true;shop.Btn_Reload();Assert.That(shop.WeeklyShop_Btn_obj.activeSelf,Is.False);c.State.Gun_Collect[15]=true;shop.Btn_Reload();yield return null;Click(shop.WeeklyShop_Btn_obj.GetComponent<Button>());yield return null;Assert.That(shop.WeeklyShop_UI.activeInHierarchy,Is.True);Assert.That(shop.menu_list.currentNum,Is.Zero);
  c.Forest.Stage_Value_Max=189;Click(At(shop.WeeklyShop_UI.transform,"Panel/Menu/Menu_Btn_1"));Assert.That(shop.menu_list.currentNum,Is.Zero);Assert.That(c.State.Recovery_WeeklyVipFirstOpened,Is.False);
  UnityEngine.Object.FindAnyObjectByType<Alert>(FindObjectsInactive.Include).gameObject.SetActive(false);c.Forest.Stage_Value_Max=190;Click(At(shop.WeeklyShop_UI.transform,"Panel/Close_Btn"));yield return null;Click(shop.WeeklyShop_Btn_obj.GetComponent<Button>());yield return null;Assert.That(shop.menu_list.currentNum,Is.EqualTo(1));Assert.That(shop.VIP_Locked_obj.activeSelf,Is.False);Assert.That(c.State.Recovery_WeeklyVipFirstOpened,Is.True);
  Click(At(shop.WeeklyShop_UI.transform,"Panel/Menu/Menu_Btn_0"));yield return null;Assert.That(shop.Get_Default_Menu(),Is.EqualTo(WeeklyShop_Menu.Gun));var item=shop.WeeklyShop_UI.GetComponentsInChildren<DailyGun_Item>(true).Single(i=>i.Item_Idx==0);Click(item.gun_item.GetComponent<Button>());yield return null;Assert.That(c.Guns.gun_info_ui.gameObject.activeInHierarchy,Is.True);Assert.That(c.Guns.gun_info_ui.Name_txt.text,Is.EqualTo(c.Guns.Gun_list[c.WeeklyGuns.GunNum_return(0)].Name));c.Guns.gun_info_ui.Close();
  string report=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../reverse/com.Chodun.CatGunner/1.1.61-vc257/reports/visual/weekly-shop-gpu.png"));ScreenCapture.CaptureScreenshot(report);yield return new WaitForSeconds(.1f);c.SaveNow();yield return Load();c=RecoveryForestClient.Instance;Assert.That(c.State.Recovery_WeeklyVipFirstOpened,Is.True);Assert.That(c.WeeklyShop.Get_Default_Menu(),Is.EqualTo(WeeklyShop_Menu.Gun));
 }
 [UnityTest]public IEnumerator WeeklyRotationPrefixLimitsAndUnavailableStoreNeverGrant()
 {
  yield return Load();var c=RecoveryForestClient.Instance;var daily=c.WeeklyGuns;var date=new DateTime(2024,1,1);c.RaidMode.Now=()=>date;daily.Week_Refresh();Assert.That(Enumerable.Range(0,3).Select(daily.GunNum_return),Is.EqualTo(new[]{20,30,35}));daily.Purchase_Counts[0]=2;daily.Purchase_Counts[1]=1;daily.Capture();Assert.That(daily.Is_Purchasable(0),Is.False);Assert.That(daily.Remain_Count_return(1),Is.EqualTo(1));date=date.AddDays(7);daily.Week_Refresh();Assert.That(daily.Purchase_Counts,Is.EqualTo(new int[3]));Assert.That(Enumerable.Range(0,3).Select(daily.GunNum_return),Is.EqualTo(new[]{21,31,36}));Assert.That(daily.Week_Key,Is.EqualTo("20240108"));
  c.State.Gun_Collect[15]=true;c.WeeklyShop.Btn_Reload();yield return null;Click(c.WeeklyShop.WeeklyShop_Btn_obj.GetComponent<Button>());yield return null;var item=c.WeeklyShop.WeeklyShop_UI.GetComponentsInChildren<DailyGun_Item>(true).Single(i=>i.Item_Idx==0);item.First_Reload();item.Reload();var popup=c.WeeklyShop.WeeklyShop_UI.GetComponentInChildren<DailyGun_popup>(true);Assert.That(popup.Time_txt.text,Is.EqualTo(daily.Remain_str_return()));date=date.AddSeconds(2);yield return new WaitForSecondsRealtime(1.1f);Assert.That(popup.Time_txt.text,Is.EqualTo(daily.Remain_str_return()));var wallet=(c.State.Dia,c.State.PetCoin,c.State.StarGem);var owned=(int[])c.State.Owned_Gun_list.Clone();var counts=(int[])daily.Purchase_Counts.Clone();Click(item.GetComponent<Button>());yield return null;Assert.That((c.State.Dia,c.State.PetCoin,c.State.StarGem),Is.EqualTo(wallet));Assert.That(c.State.Owned_Gun_list,Is.EqualTo(owned));Assert.That(daily.Purchase_Counts,Is.EqualTo(counts));Assert.That(UnityEngine.Object.FindAnyObjectByType<Alert>(FindObjectsInactive.Include).GetComponentInChildren<TMPro.TextMeshProUGUI>(true).text,Does.Contain("Store"));
 }
 [UnityTest]public IEnumerator NaturalRaidFeedsBothTaskTypesRealClaimAndColdReloadCannotDuplicate()
 {
  natural=true;yield return Load();var c=RecoveryForestClient.Instance;var raid=c.RaidMode;var missions=c.RaidMissions;raid.Now=()=>new DateTime(2024,1,1);raid.Season_Check();missions.Refresh_Clear();c.State.Owned_Gun_list[0]=30;c.State.Upgrade_Lv[0]=100;c.State.Upgrade_Lv[1]=100;raid.Panel_Open();raid.Gun_UnSelect(1);yield return new WaitForSeconds(.4f);Click(raid.raidStart_ui.Enter_Normal_obj.GetComponent<Button>());
  float started=Time.realtimeSinceStartup,deadline=started+75;while((raid.Entering||raid.Playing)&&Time.realtimeSinceStartup<deadline)yield return null;Assert.That(raid.Playing,Is.False);Assert.That(raid.Score_Now,Is.GreaterThanOrEqualTo(1));Assert.That(Time.realtimeSinceStartup-started,Is.GreaterThan(61));Assert.That(missions.State_return(0),Is.EqualTo(1));Assert.That(missions.State_return(3),Is.EqualTo(1));Assert.That(raid.Season_TryCount,Is.EqualTo(1));
  raid.Game_Exit();yield return new WaitForSeconds(2);foreach(var cat in c.Team.Cat_list)cat.GetComponent<ForestCombatAcceptance>().enabled=false;raid.Panel_Open();yield return null;var hud=raid.raidStart_ui.GetComponentInChildren<Raid_Mission_HUD>(true);Assert.That(hud.Alert_obj.activeSelf,Is.True);Click(hud.GetComponent<Button>());yield return null;var ui=missions.mission_ui;Assert.That(ui.gameObject.activeInHierarchy,Is.True);var item=ui.Mission_item_list[0];Assert.That(item.Value_txt.text,Is.EqualTo("1/1"));int gems=c.State.StarGem;Click(item.Claimable_obj.GetComponentInChildren<Button>(true));yield return null;Assert.That(c.State.StarGem,Is.EqualTo(gems+300));Assert.That(missions.State_return(0),Is.EqualTo(2));Assert.That(missions.Reward_Get(0),Is.False);Assert.That(c.State.StarGem,Is.EqualTo(gems+300));Click(item.ReClaimable_obj.GetComponentInChildren<Button>(true));yield return null;Assert.That(missions.Ticket_Popup_obj.activeInHierarchy,Is.True);Assert.That(missions.Ticket_Purchased,Is.False);Assert.That(c.State.StarGem,Is.EqualTo(gems+300));missions.Ticket_Popup_Close();
  string report=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../reverse/com.Chodun.CatGunner/1.1.61-vc257/reports/visual/raid-missions-gpu.png"));ScreenCapture.CaptureScreenshot(report);yield return new WaitForSeconds(.1f);c.SaveNow();var saved=new OriginalSaveArchive(folder).Load();Assert.That(saved.RaidMission_Reward_Get[0],Is.True);Assert.That(saved.RaidMission_Clear[3],Is.True);Assert.That(saved.StarGem,Is.EqualTo(gems+300));
  // The fixed-calendar fixture must also be supplied before mission Bind on reload.
  natural=false;SceneManager.sceneLoaded+=FixedCalendar;yield return Load();SceneManager.sceneLoaded-=FixedCalendar;c=RecoveryForestClient.Instance;Assert.That(c.RaidMissions.State_return(0),Is.EqualTo(2));Assert.That(c.RaidMissions.Reward_Get(0),Is.False);Assert.That(c.State.StarGem,Is.EqualTo(gems+300));
 }
 private static void FixedCalendar(Scene scene,LoadSceneMode mode){if(scene.name=="RecoveredClient")scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Raid_manager>(true)).Single().Now=()=>new DateTime(2024,1,1);}
 [UnityTest]public IEnumerator MissionLegacyPrefixSeasonResetPaidFlagsAndBatchClaimAreIndependent()
 {
  yield return Load();var c=RecoveryForestClient.Instance;var date=new DateTime(2024,1,1);c.RaidMode.Now=()=>date;c.RaidMode.Season_Check();var m=c.RaidMissions;var s=new OriginalSaveData{RaidMission_Season_Index=0,RaidMission_Clear=new[]{true},RaidMission_Reward_Get=new[]{true},RaidMission_Reward_ReGet=Array.Empty<bool>(),RaidMission_Ticket=false};m.LoadFromSaveData(s);Assert.That(m.Mission_Clear.Length,Is.EqualTo(8));Assert.That(m.State_return(0),Is.EqualTo(2));Assert.That(s.RaidMission_Clear.Length,Is.EqualTo(1));m.Progress_return(0,out int value,out int max);Assert.That((value,max),Is.EqualTo((1,1)));int gems=c.State.StarGem;Assert.That(m.Reward_GetAll(),Is.Zero);m.Ticket_Purchase("test");Assert.That(m.Ticket_Purchased,Is.False);Assert.That(c.State.StarGem,Is.EqualTo(gems));
  c.RaidMode.Season_TryCount=7;c.RaidMode.Season_BestLevel=30;m.Refresh_Clear();Assert.That(m.Clear_Count,Is.EqualTo(8));Assert.That(m.Reward_GetAll(),Is.EqualTo(7));Assert.That(c.State.StarGem,Is.EqualTo(gems+3300));Assert.That(m.Reward_GetAll(),Is.Zero);Assert.That(m.Reward_Total,Is.EqualTo(3600));date=date.AddDays(7);m.Refresh_Clear();Assert.That(m.Clear_Count,Is.Zero);Assert.That(m.Mission_Reward_Get.Any(x=>x),Is.False);Assert.That(m.Mission_Reward_ReGet.Any(x=>x),Is.False);Assert.That(m.Ticket_Purchased,Is.False);Assert.That(c.State.StarGem,Is.EqualTo(gems+3300));
 }
 [UnityTest]public IEnumerator SourceLoopsAnimateAndResetWithoutTouchingCurrencyOrInterceptingButtons()
 {
  yield return Load();var c=RecoveryForestClient.Instance;c.State.Gun_Collect[15]=true;c.WeeklyShop.Panel_Open();yield return null;var effects=UnityEngine.Object.FindObjectsByType<RecoveryWeeklyUiTween>(FindObjectsInactive.Include,FindObjectsSortMode.None);Assert.That(effects.Length,Is.EqualTo(10));var spin=effects.First(x=>x.AnimationType==4&&x.transform.IsChildOf(c.WeeklyShop.WeeklyShop_UI.transform));float angle=spin.transform.localEulerAngles.z;yield return new WaitForSeconds(.4f);Assert.That(Mathf.Abs(Mathf.DeltaAngle(angle,spin.transform.localEulerAngles.z)),Is.GreaterThan(20));c.WeeklyShop.Panel_Close();c.RaidMode.Panel_Open();c.RaidMissions.Open_Popup();yield return null;var visible=c.RaidMissions.mission_ui.GetComponentsInChildren<RecoveryWeeklyUiTween>(true).Single();Assert.That(visible.gameObject.activeInHierarchy,Is.True);var scale=visible.transform.localScale;var wallet=(c.State.StarGem,c.State.Dia);yield return new WaitForSeconds(.4f);Assert.That(Vector3.Distance(scale,visible.transform.localScale),Is.GreaterThan(.001f));c.RaidMissions.Close_Popup();yield return null;Assert.That(visible.transform.localScale,Is.EqualTo(visible.SourceScale));Assert.That((c.State.StarGem,c.State.Dia),Is.EqualTo(wallet));
 }
 [Test]public void OversizedWeeklyArraysRejectedBeforeAnySaveAndSortUsesOriginalStatePriority(){var state=new OriginalSaveData{Upgrade_Lv=new int[3],Selected_items=new[]{0,-1,-1},RaidMission_Clear=new bool[9]};Assert.Throws<InvalidOperationException>(()=>RecoveryForestClient.ValidateSupportedState(state));Assert.That(new[]{0,1,2,3}.Select(s=>Raid_Mission_UI.Priority(s,false)),Is.EqualTo(new[]{2,0,1,3}));Assert.That(new[]{0,1,2,3}.Select(s=>Raid_Mission_UI.Priority(s,true)),Is.EqualTo(new[]{1,0,0,2}));}
}
